# November 18, 2026: Saskatoon and the South Branch country north of it (Batoche, Fish Creek, St. Laurent, Fort Carlton,
# Rosthern, Blaine Lake), Saskatchewan. Region sk drawn at random by tools/choose.py --claim; the first places in the
# province. Sources were opened in this session: Wikipedia as raw text (tools/wiki_raw.py); the Canadian Register of
# Historic Places (historicplaces.ca) statements for each designated place; City of Saskatoon heritage-register, park and
# history pages; Parks Canada's Tourond's Coulee page; the Museums Association of Saskatchewan listings (Batoche, Marr
# Residence); Tourism Saskatchewan's Fort Carlton listing; the Seager Wheeler Farm, Wanuskewin, Diefenbaker Canada Centre
# and Town of Borden pages, all through tools/page.py. Parks Canada's Batoche hours page and Sask Parks' Fort Carlton page are
# drawn by script and could not be read.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
def YXE(t,s): return ['City of Saskatoon heritage register: '+t,'https://saskatoon.ca/heritage-register/'+s]
BATCH={'key':'sk_fwmi','label':'Saskatoon, Batoche and the South Branch, Saskatchewan','added':'2026-11-18 20:49'}
MAS_B=L('Museums Association of Saskatchewan: Batoche National Historic Site','https://saskmuseums.org/places/batoche-national-historic-site/')
